(async()=>{const response=await fetch("game.json");const config=await response.json();const coreVersion=config.game.requiredCoreVersion||"0.1.2";const useCDN=config.game.useCDN!==false;let baseUrl;if(useCDN){baseUrl=`https://cdn.jsdelivr.net/gh/greenjug/scenie@v${coreVersion}`}else{baseUrl="../../../../js/scenie-framework"}let emitVersion=null;let emitVerbosity="console";if(config.game.requires&&Array.isArray(config.game.requires)){const emitReq=config.game.requires.find(req=>typeof req==="object"&&req.module==="emit");if(emitReq){emitVersion=emitReq.version;emitVerbosity=emitReq.verbosity||"console";window.emitVerbosity=emitVerbosity;let emitBaseUrl;if(useCDN){emitBaseUrl=`https://cdn.jsdelivr.net/gh/greenjug/scenie@v${emitVersion}`}else{emitBaseUrl="../../../../js/scenie-framework"}await loadScript(`${emitBaseUrl}/emit.js`)}}await loadScript(`${baseUrl}/core.js`);if(config.game.requires&&Array.isArray(config.game.requires)){for(const req of config.game.requires){let scriptName,moduleVersion;if(typeof req==="string"){scriptName=req;moduleVersion=config.game[`required${scriptName.charAt(0).toUpperCase()+scriptName.slice(1)}Version`]||coreVersion}else{scriptName=req.module;moduleVersion=req.version;if(scriptName==="emit")continue}let moduleBaseUrl;if(useCDN){moduleBaseUrl=`https://cdn.jsdelivr.net/gh/greenjug/scenie@v${moduleVersion}`}else{moduleBaseUrl="../../../../js/scenie-framework"}await loadScript(`${moduleBaseUrl}/${scriptName}.js`)}}new Game(config)})();function loadScript(src){return new Promise((resolve,reject)=>{const script=document.createElement("script");script.src=src;script.onload=resolve;script.onerror=reject;document.head.appendChild(script)})}